    case 62:
      ACCEPT_TOKEN(sym_loop_break);
      END_STATE();
    case 63:
      if (lookahead == 'x') ADVANCE(70);
      END_STATE();
    case 64:
      if (lookahead == 'n') ADVANCE(71);
      END_STATE();
    case 65:
      ACCEPT_TOKEN(anon_sym_false);
      END_STATE();
    case 66:
      if (lookahead == 't') ADVANCE(72);
      END_STATE();
    case 67:
