    case 76:
      if (lookahead == 'e') ADVANCE(78);
      END_STATE();
    case 77:
      ACCEPT_TOKEN(anon_sym_include);
      END_STATE();
    case 78:
      ACCEPT_TOKEN(sym_loop_continue);
      END_STATE();
    default:
      return false;
